/// [key] için [lang] dilindeki metin; {ad} yer tutucuları [p] ile dolar.
String appTx(String key, String lang, [Map<String, Object> p = const {}]) {
  var s = Strings.pick(kAppTx[key] ?? [key, key], lang);
  p.forEach((k, v) => s = s.replaceAll('{$k}', '$v'));
  return s;
}
